import{z as n,x as A,o as E,c as d,q as i,j as o,D as e,d as s,s as l,S as B,b as r}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"IDS / IPS","description":"","frontmatter":{"title":"IDS / IPS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ids-ips.md","filePath":"cs/ids-ips.md","lastUpdated":1791063341000}'),p={name:"cs/ids-ips.md"};function S(D,a,I,c,h,P){const t=A("Mermaid");return E(),d("div",null,[a[2]||(a[2]=i('<h1 id="ids-ips" tabindex="-1">IDS / IPS <a class="header-anchor" href="#ids-ips" aria-label="Permalink to &quot;IDS / IPS&quot;">​</a></h1><div class="epigraph"><p>入侵检测看流量或主机事件是否像已知滥用；防护系统还加上阻断。它们识别的是模式与异常，不是应用不变量。漏报与误报同时存在，所以要和日志、响应流程一起设计。</p><footer>—— 据 Roesch, Snort；Paxson, Bro；对照 NIST SP 800-94</footer></div><p>上一课<a href="/cs/api-security-bola">BOLA</a>在应用授权。缺口是<strong>网络层可见性</strong>：应用仍会漏，流量侧能否看见扫描、已知利用特征、C2 形态。本课分工 IDS 与 IPS，不写逃避检测的步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>防火墙课管策略放行。<a href="/cs/firewall-state">防火墙</a>不深检载荷。IDS：旁路告警；IPS：串接阻断。缺口是部署点（网络、主机）与加密流量的盲区。</p><p><span class="marginnote">直觉类比：IDS 是监控室的保安——看得见、能喊人，拦不住正在发生的撬门；IPS 是装在门上的闸机——当场拦人，但认错（误报）就把真顾客挡在门外。保安出错没代价，闸机出错直接影响可用性，这是两者部署取舍的核心。</span></p><h3 id="加密后载荷" tabindex="-1">加密后载荷 <a class="header-anchor" href="#加密后载荷" aria-label="Permalink to &quot;加密后载荷&quot;">​</a></h3><p>TLS 后 IDS 只见五元组与 SNI 一类元数据，除非终止 TLS——那是另一威胁模型。</p><p><span class="marginnote">SP 800-94。Snort/Bro 历史。禁止编写逃避 IDS 的教程。下一课规则语言。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照误报成本（可用性）与漏报成本。主机 IDS 看系统调用。下一课 Snort/Suricata 规则形态。</p><p><span class="marginnote">为什么误报是「合同」：每天百万级连接里若误报率百分之一，值班员就会被假警报淹没，真告警也跟着被忽略（狼来了效应）。所以旁路 IDS 宁可偏松、再靠响应流程核实；敢串接的 IPS 规则必须极准，因为每一次误报都在直接丢正常流量。</span></p>',13)),(E(),o(B,null,{default:e(()=>[l(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20TAP%5B%22%E6%B5%81%E9%87%8F%E5%A4%8D%E5%88%B6%22%5D%20--%3E%20IDS%5B%22%E6%A3%80%E6%B5%8B%E5%91%8A%E8%AD%A6%22%5D%0A%20%20INLINE%5B%22%E4%B8%B2%E6%8E%A5%22%5D%20--%3E%20IPS%5B%22%E6%A3%80%E6%B5%8B%E5%B9%B6%E9%98%BB%E6%96%AD%22%5D%0A%20%20TLS%5B%22%E5%8A%A0%E5%AF%86%22%5D%20--%3E%20META%5B%22%E5%85%83%E6%95%B0%E6%8D%AE%E5%8F%AF%E8%A7%81%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[s("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"检测服务完整与可用的观测。它不修复 BOLA。规则下一课把「像什么」写成可维护的签名。",-1)),(E(),o(B,null,{default:e(()=>[l(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E8%BF%9B%E5%85%A5%E7%9A%84%E6%B5%81%E9%87%8F%22%5D%20--%3E%20TAP%5B%22%E9%95%9C%E5%83%8F%E4%B8%80%E4%BB%BD%E7%BB%99%E6%97%81%E8%B7%AF%20IDS%22%5D%0A%20%20F%20--%3E%20INLINE%5B%22%E5%8E%9F%E8%B7%AF%E5%BE%84%E7%A9%BF%E8%BF%87%E4%B8%B2%E6%8E%A5%20IPS%22%5D%0A%20%20TAP%20--%3E%20AL%5B%22%E5%91%BD%E4%B8%AD%EF%BC%9A%E5%8F%AA%E8%83%BD%E5%91%8A%E8%AD%A6%EF%BC%8C%E6%B5%81%E9%87%8F%E7%85%A7%E8%B5%B0%22%5D%0A%20%20INLINE%20--%3E%20BLK%5B%22%E5%91%BD%E4%B8%AD%EF%BC%9A%E7%9B%B4%E6%8E%A5%E4%B8%A2%E5%BC%83%E6%88%96%E9%87%8D%E7%BD%AE%22%5D%0A%20%20INLINE%20--%3E%20PASS%5B%22%E6%9C%AA%E5%91%BD%E4%B8%AD%EF%BC%9A%E6%94%BE%E8%A1%8C%22%5D%0A%20%20AL%20--%3E%20OPS%5B%22%E5%91%8A%E8%AD%A6%E4%BA%A4%E5%93%8D%E5%BA%94%E6%B5%81%E7%A8%8B%E5%A4%84%E7%90%86%22%5D%0A%20%20BLK%20--%3E%20OPS%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p><span class="marginnote">常见误区：以为 IDS 能看见 TLS 里的内容。加密后可用的只剩五元组、包大小与时序、SNI 等元数据——像只能看到信封的大小、重量和收件人，读不到信本身。所以「检测服务的完整与可用」首先要保证观测点没被绕开、没被加密挤成瞎子。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写逃避。下一课规则。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>应用授权之后，流量侧仍要观测。</li><li>IDS 告警，IPS 阻断；加密后见元数据。</li><li>误报与漏报是合同，不是调参能消掉。</li><li>下一课 IDS 规则。</li><li>出处：Roesch, Snort；Paxson, Bro；NIST SP 800-94。</li></ul>',5))])}const f=n(p,[["render",S]]);export{u as __pageData,f as default};
